def sift_down(items, root, size):
    while True:
        child = 2 * root + 1
        if child >= size:
            return
        if child + 1 < size and items[child + 1] > items[child]:
            child += 1
        if items[child] > items[root]:
            items[root], items[child] = items[child], items[root]
            root = child
        else:
            return

def build_heap(items):
    for i in range(len(items) // 2 - 1, -1, -1):
        sift_down(items, i, len(items))

def heap_sort(items):
    build_heap(items)
    for end in range(len(items) - 1, 0, -1):
        items[0], items[end] = items[end], items[0]
        sift_down(items, 0, end)

